const sub = $("GET /pitches").first().json.jwtPayload.sub;
const today = $today.toFormat("yyyy-MM-dd");
// Everyone gets open pitches, plus cancelled ones until their deadline, so
// the people who were interested can read the organizer's reason, and expired
// ones until their start date, while the organizer can still reopen them. The
// caller also gets every pitch they organize, in any status, for /me.
const pitches = $("Get listed pitches")
  .all()
  .map((i) => i.json)
  .filter(
    (r) =>
      r.pitch_id &&
      (r.status === "open" ||
        (r.status === "cancelled" && String(r.deadline) >= today) ||
        (r.status === "expired" && String(r.start_date) >= today) ||
        r.organizer === sub),
  );
const interest = $("Get interest").all().map((i) => i.json).filter((r) => r.pitch_id);
const profileBySub = new Map(
  $("Get profiles").all().map((i) => i.json).filter((p) => p.user_sub).map((p) => [p.user_sub, p]),
);
const orEmpty = (value) => (typeof value === "string" && value.trim() ? value.trim() : null);
// Who is interested, oldest first (the order spots go in if the pitch
// becomes a trip). One entry per person. Everyone gets this list: display
// fields only, and the caller flagged with isMe, never anyone's sub or email.
const interestedPeople = (pitchId) => {
  const seen = new Set();
  return interest
    .filter((r) => r.pitch_id === pitchId)
    .sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)))
    .filter((r) => !seen.has(r.user_sub) && seen.add(r.user_sub))
    .map((r) => {
      const profile = profileBySub.get(r.user_sub) ?? {};
      return {
        name: profile.name ?? "",
        team: orEmpty(profile.team),
        jobTitle: orEmpty(profile.jobTitle),
        isMe: r.user_sub === sub,
      };
    });
};

return [
  {
    json: {
      pitches: pitches.map((row) => {
        const people = interestedPeople(row.pitch_id);
        const organizerName = profileBySub.get(row.organizer)?.name ?? "";
        return {
          pitchId: row.pitch_id,
          status: row.status,
          cancelReason: row.status === "cancelled" ? (row.cancel_reason ?? "") : "",
          place: row.place,
          startDate: row.start_date ?? "",
          endDate: row.end_date ?? "",
          description: row.description ?? "",
          accommodationUrl: row.accommodation_url ?? "",
          imageUrl: row.image_url ?? "",
          imageAlt: row.image_alt ?? "",
          capacity: row.capacity,
          threshold: row.threshold,
          deadline: row.deadline ?? "",
          costEstimate: typeof row.cost_estimate === "number" ? row.cost_estimate : null,
          costIncludes: row.cost_includes ?? "",
          interested: people.length,
          interestedPeople: people,
          interestedByMe: people.some((person) => person.isMe),
          // A flag, never the sub: everyone gets this list.
          organizedByMe: row.organizer === sub,
          organizer: organizerName ? { name: organizerName } : null,
          // Set by "Slack Bot Notifier" when the pitch was announced.
          slackUrl: row.slack_url ?? "",
        };
      }),
      slackChannelUrl: $vars.SLACK_CHANNEL_URL ?? "",
    },
  },
];
